data.query:
query ($workunitId: String!) {
  productionSetupOutput(where: {workunitId: {_eq: $workunitId}}) {
    total
    edges {
      node {
        id
        unitPerCycle
        produced
        quantity
        scrapped
        standardPackQuantity
        customData
        workunitId
        workunit {
          currentStateHistoryId
          currentStateHistory {
            modeId
            stateId
            scheduleId
          }
        }
        workOrderProcessId
        workOrderProcessDistribution {
          productionOperators
          setupOperators
          idealDuration
          standardDuration
          setupDuration
          quantity
          workOrderProcess{
            processId
            workOrder{
              product{
                code
                name  
                id
              }
              productStrategy{
                productStrategyProcesses{
                  total
                  edges{
                    node{
                      id
                      processId
                      productStrategyProcessSteps{
                        edges{
                          node{
                            id
                            code
                            min
                            max
                            target
                            description
                            expectedDuration
                            sequence
                            color
                            fileId
                            unitId
                            url
                            productStrategyProcessBomId
                            productStrategyProcessStepType{
                              id
                              code
                            }
                          }
                        }
                      }

                    }
                  }
                }
              }
            }
          }
        }
        productionSetupOutputSteps{
          edges{
            node{
              id
            }
          }
        }
      }
    }
  }
  workunit(where: {id: {_eq: $workunitId}}) {
    edges {
      node {
        id
        scheduleGroupId
        currentProductionRunId
        currentProductionRun {
          startAt
          active
        }
        productionSetupOperators {
          total
        }
        currentStateHistoryId
      }
    }
  }
  setting(where: {id: {_eq: "TimeZone"}}) {
    edges {
      node {
        defaultValue
      }
    }
  }
}

