mutation ($runPayload: [ProductionRunCreatePayloadInput!]!, $workunitStateHistoryPayload: [WorkunitStateHistoryCreatePayloadInput!]!, $workunitPayload: [WorkunitUpdatePayloadInput!]!) {
  createProductionRun(payload: $runPayload) {
    id
  }
  createWorkunitStateHistory(payload: $workunitStateHistoryPayload) {
    id
  }
  updateWorkunit(payload: $workunitPayload) {
    id
  }
}

mutation (
  $runPayload: [ProductionRunUpdatePayloadInput!]!,
  $workunitStateHistoryPayload: [WorkunitStateHistoryCreatePayloadInput!]!
  $outputStepPayload: [ProductionSetupOutputStepDeletePayloadInput!]!,
  $workunitPayload: [WorkunitUpdatePayloadInput!]!,
){
  createWorkunitStateHistory(payload: $workunitStateHistoryPayload){ id }
  updateProductionRun(payload: $runPayload){ id }  
  deleteProductionSetupOutputStep(payload: $outputStepPayload){ id } 
  updateWorkunit(payload: $workunitPayload){ id }  
}

