    $modeStart := $mode.occurAt? $moment($mode.occurAt);
    $modeEnd := $mode.endAt? $moment($mode.endAt);

    $endBoundObj := $moment($endBound);
    $startBoundObj := $moment($startBound);

    $start := $mode.occurAt and $modeStart.isAfter($startBound)? $modeStart : $startBoundObj;
    $end := $mode.endAt and $modeEnd.isBefore($endBound)? $modeEnd : $endBoundObj;

    $isNilOrEmpty($mode.occurAt) and $isNilOrEmpty($mode.endAt)? 
      $throw("Mode has no occurAt or endAt", $mode) :
      $end.diff($start, "seconds")   

  )};
  $time := $calculateSeconds(productionRun.edges.node.startAt, $state.context.endAt, ?);

  $totalProduced := $coalesce([$sum([productionHistory.edges.node[scrap=false].quantity]), 0 ]);
  $totalScrap := $coalesce([$sum([productionHistory.edges.node[scrap=true].quantity]), 0 ]);
  $totalProduction := $totalProduced + $totalScrap;

 /* $totalExcludedProduced := $coalesce( [$sum(productionHistory.edges.node[transactionTypeId="Production Add" and includeInProductionCounts=false].quantity), 0 ]);
  $totalExcludedScrap := $coalesce([$sum(productionHistory.edges.node[transactionTypeId="Scrap Add" and includeInProductionCounts = false].quantity), 0]);
