  $idealRate := $momentDuration($idealAggregate).asSeconds();

  $end := $moment( $state.context.endAt );
  $start := $moment( productionRun.edges.node.startAt );
  $duration := $end.diff($start, "seconds");

  $idealRateSeconds := $idealRate > 0 ? $idealRate : 0;
  $now := $moment().format();

  /* Mode Type is changeover */
  $changeoverTime := $reduce(
   [workunitStateHistory.edges.node[modeId = "Changeover"]],
    function($acc, $crr){ $acc + $time($crr) },
    0
  );
   /* Event Type is plannedDowntime */
  $plannedDowntime := $reduce(
    [workunitStateHistory.edges.node[state.stateCategory.id = "Planned Downtime"]],
    function($acc, $crr){ $acc + $time($crr) },
