        "unplannedDowntimeDuration": $unplannedDowntime > 0 ? $momentDuration($unplannedDowntime) : 'PT0S',
        "workunitId": $state.context.productionSetup.edges.node.workunitId,
        "laborDuration": $runTime ? $momentDuration($runTime *  $runCrewSize, 'seconds') : 'PT0S',
        "availability": $floor($availability * 100),
        "oee": $floor($oee * 100),
        "active": false
      }
    },
    "workunitPayload":{
      "where": { "id": $workunit.id },
      "update":{ "currentProductionRunId": null, "currentStateHistoryId": $workunitStateHistoryId }
    },
    "workunitStateHistoryPayload":{
      "create": $merge([
