          "transactionTypeId": "Production Setup clear",
          "productionRunId": productionRun.edges.node.id,
          "workunitId": $workunit.id,
          "scheduleId": $scheduleId,
          "occurAt": $moment(),
          "message": "Production Run: " & productionRun.edges.node.number & "Ended" ,
          "modeId": $state.context.productionSetupOutput.edges.node.workunit.currentStateHistory.modeId,
          "stateId": $state.context.productionSetupOutput.edges.node.workunit.currentStateHistory.stateId
        },
        $state.context.workunit.edges.node.currentStateHistory
      ])
