  $workunitId: String!,
  $productionRunId: String!,
  $startTime: DateTime!,
  $endTime: DateTime!
) {
  productionRun(where:{ id:{_eq: $productionRunId }}){
    edges{
      node{
        id
        runCrewSize
        crewAggregate
        standardAggregate
        startAt
        idealAggregate
        startAt
      }
    }
  }
  productionHistory(where: {productionRunId: {_eq: $productionRunId}}) {
    total
    edges {
      node {
        id
        quantity
        scrap
        externalId
        scrapReasonId
        workOrderProcessDistribution {
          workOrderProcessId
          workOrderProcess {
            workOrderId
            workOrder {
              number
            }
          }
        }
        workOrderProcessDistributionId
        productId
        creditedAt
        occurAt
        customData
        productionRunId
        scrapReasonId
        workunitId
      }
    }
  }
  workunitStateHistory(
    where:{ 
      workunitId:{_eq: $workunitId}
      _or:[
        {
          _and:[
            { occurAt:{_gte: $startTime} }
            { occurAt:{_lt: $endTime} }
          ]
        },
        {
          _and:[
            { endAt:{_gte: $startTime} }
